<script setup lang="ts">
import { onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips } from "@/util/tips";
import { GetPermissionAuditList } from "@/apis/permission";
import { GetAuditActionText } from "@/types/permission";
import type { PermissionAuditItem } from "@/types/permission";

const { globalProperties } = useCurrentInstance();

const loading = ref(false);
const items = ref([] as PermissionAuditItem[]);
const hasMore = ref(false);
const pageSize = 20;

const loadMore = async () => {
  loading.value = true;
  try {
    const cursorId = items.value.length > 0 ? items.value[items.value.length - 1].id : 0;
    const res = await GetPermissionAuditList(cursorId, pageSize);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    items.value = [...items.value, ...(res.data?.items ?? [])];
    hasMore.value = res.data?.has_more ?? false;
  } finally {
    loading.value = false;
  }
};

onMounted(loadMore);

const handleRefresh = () => {
  items.value = [];
  hasMore.value = false;
  loadMore();
};

/**
 * 把审计的 detail（JSON 文本）渲染成一句人话。
 *
 * 不同动作记录的差异形状不同（权限点集合 / 角色集合 / 成员 id 集合），后端刻意用
 * jsonb 存而不是套一张宽表。这里按已知字段挑选展示，遇到不认识的形状就退回原始文本——
 * 不做「猜字段」，否则后端新增动作时前端会显示出一个误导性的空摘要。
 */
const formatDetail = (detail: string): string => {
  if (!detail) {
    return "-";
  }
  try {
    const parsed = JSON.parse(detail) as Record<string, unknown>;
    const parts: string[] = [];
    const pushList = (label: string, value: unknown) => {
      if (Array.isArray(value) && value.length > 0) {
        parts.push(`${label}：${value.join("、")}`);
      }
    };
    pushList("新增权限", parsed.permissions_added);
    pushList("移除权限", parsed.permissions_removed);
    pushList("新增角色", parsed.roles_added);
    pushList("移除角色", parsed.roles_removed);
    pushList("加入组", parsed.groups_added);
    pushList("移出组", parsed.groups_removed);
    pushList("新增成员", parsed.added);
    pushList("移除成员", parsed.removed);
    if (typeof parsed.name === "string" && parsed.name) {
      parts.push(`名称：${parsed.name}`);
    }
    if (typeof parsed.member_count === "number") {
      parts.push(`当时成员数：${parsed.member_count}`);
    }
    return parts.length > 0 ? parts.join("；") : detail;
  } catch {
    return detail;
  }
};
</script>

<template>
  <div class="permission-panel">
    <div class="panel-toolbar">
      <t-button variant="outline" :loading="loading" @click="handleRefresh">刷新</t-button>
      <span class="panel-hint">
        记录每一次授权变更（谁、何时、对谁做了什么）。按时间倒序，每次加载 20 条。
      </span>
    </div>

    <t-table
      row-key="id"
      :data="items"
      :loading="loading"
      :scroll="{ x: 1000 }"
      :columns="[
        { title: '时间', colKey: 'insert_time', width: 170 },
        { title: '操作人', colKey: 'operator_name', width: 140 },
        { title: '动作', colKey: 'action', width: 130 },
        { title: '目标', colKey: 'target', width: 180 },
        { title: '变更内容', colKey: 'detail', width: 360 },
      ]"
    >
      <template #action="{ row }">
        <t-tag size="small" variant="light">{{ GetAuditActionText(row.action) }}</t-tag>
      </template>

      <template #target="{ row }">
        <span>{{ row.target_type }} / {{ row.target_id }}</span>
      </template>

      <template #detail="{ row }">
        <span>{{ formatDetail(row.detail) }}</span>
      </template>
    </t-table>

    <div class="panel-more">
      <t-button v-if="hasMore" variant="outline" :loading="loading" @click="loadMore">
        加载更多
      </t-button>
      <span v-else-if="items.length > 0" class="panel-hint">已到末尾</span>
    </div>
  </div>
</template>

