<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetPermissionCatalog,
  GetPermissionGroupList,
  GetPermissionRoleList,
  GetPermissionUserAuth,
  PostPermissionUserGroupSave,
  PostPermissionUserRoleSave,
} from "@/apis/permission";
import { PostUserParse } from "@/apis/user";
import { useUserStore } from "@/stores/user";
import type { PermissionGroup, RoleInfo, UserAuthInfo, UserGroupInfo } from "@/types/permission";

const { globalProperties } = useCurrentInstance();
const userStore = useUserStore();

const searchName = ref("");
const loading = ref(false);
const saving = ref(false);

const auth = ref(null as UserAuthInfo | null);
const roles = ref([] as RoleInfo[]);
const groups = ref([] as UserGroupInfo[]);
const catalog = ref([] as PermissionGroup[]);

// 编辑中的本地副本：改完点保存才提交，避免误触即生效
const directRoles = ref([] as string[]);
const groupIds = ref([] as number[]);

const permissionNames = computed(() => {
  const map: Record<string, string> = {};
  for (const group of catalog.value) {
    for (const item of group.items) {
      map[item.key] = item.name;
    }
  }
  return map;
});

/** 角色 key → 该角色携带的权限点，用于把「有效权限点」拆解回它的来源 */
const rolePermissions = computed(() => {
  const map: Record<string, string[]> = {};
  for (const role of roles.value) {
    map[role.key] = role.permissions;
  }
  return map;
});

const roleOptions = computed(() =>
  roles.value.map((role) => ({
    value: role.key,
    label: role.is_super ? `${role.name || role.key}（超管）` : role.name || role.key,
  }))
);

const groupOptions = computed(() =>
  groups.value.map((group) => ({
    value: group.id,
    label: `${group.name || group.key}（${group.roles.length} 个角色）`,
  }))
);

/** 是否在编辑自己的授权：后端会拒绝（防自提权），前端提前提示以免白跑一次请求 */
const isSelf = computed(() => auth.value !== null && auth.value.user_id === userStore.getUserId);

/**
 * 所属用户组带来的角色。
 *
 * 从「组绑定了哪些角色」推导，而不是用「有效角色 − 直接角色」：后者在**同一个角色既被直接
 * 授予、又由某个组带来**时，会把它整条算成直接角色，于是界面不再提示「组也在给这个角色」
 * ——而管理员恰恰需要知道这一点：只撤掉直接授权，权限不会消失。
 */
const rolesFromGroups = computed(() => {
  const result = new Set<string>();
  for (const groupId of auth.value?.group_ids ?? []) {
    const group = groups.value.find((item) => item.id === groupId);
    for (const key of group?.roles ?? []) {
      result.add(key);
    }
  }
  return [...result];
});

/**
 * 有效权限点 → 来源说明。
 *
 * 这是本页最该回答的问题：「这个权限是哪来的，我要撤该动哪里」。
 * 只看「有效权限点」的话，管理员撤掉直接角色后会发现权限还在（因为它同时来自某个组），
 * 于是以为系统没生效——这正是实测中踩到的那个语义。
 */
const permissionSource = computed(() => {
  const authValue = auth.value;
  if (authValue === null) {
    return {} as Record<string, string>;
  }
  const fromDirect = new Set<string>();
  for (const key of authValue.direct_roles) {
    for (const permission of rolePermissions.value[key] ?? []) {
      fromDirect.add(permission);
    }
  }
  const fromGroup = new Set<string>();
  for (const key of rolesFromGroups.value) {
    for (const permission of rolePermissions.value[key] ?? []) {
      fromGroup.add(permission);
    }
  }

  const result: Record<string, string> = {};
  for (const permission of authValue.permissions) {
    const inDirect = fromDirect.has(permission);
    const inGroup = fromGroup.has(permission);
    if (inDirect && inGroup) {
      result[permission] = "直接 + 继承";
    } else if (inGroup) {
      result[permission] = "继承";
    } else {
      result[permission] = "直接";
    }
  }
  return result;
});

/** 两个列表是否相同（与顺序无关） */
const sameSet = <T,>(left: T[], right: T[]) => {
  if (left.length !== right.length) {
    return false;
  }
  const set = new Set(right);
  return left.every((item) => set.has(item));
};

// 分项判断「改了没有」，而不是笼统地整表提交：
// 只提交真正变化的那部分，避免把没动过的另一边也重写一遍（那会覆盖掉别人刚做的改动）
const rolesDirty = computed(
  () => auth.value !== null && !sameSet(directRoles.value, auth.value.direct_roles)
);
const groupsDirty = computed(
  () => auth.value !== null && !sameSet(groupIds.value, auth.value.group_ids)
);
const dirty = computed(() => rolesDirty.value || groupsDirty.value);

const loadOptions = async () => {
  const [roleRes, groupRes, catalogRes] = await Promise.all([
    GetPermissionRoleList(),
    GetPermissionGroupList(),
    GetPermissionCatalog(),
  ]);
  if (roleRes.code === 0) {
    roles.value = roleRes.data ?? [];
  }
  if (groupRes.code === 0) {
    groups.value = groupRes.data ?? [];
  }
  if (catalogRes.code === 0) {
    catalog.value = catalogRes.data?.groups ?? [];
  }
};

onMounted(loadOptions);

/** 把服务端返回的授权灌进本地编辑副本（查询与保存后刷新都走这里，避免两份逻辑走偏） */
const applyAuth = (data: UserAuthInfo | null) => {
  auth.value = data;
  directRoles.value = [...(data?.direct_roles ?? [])];
  groupIds.value = [...(data?.group_ids ?? [])];
};

const handleSearch = async () => {
  const name = searchName.value.trim();
  if (!name) {
    ShowErrorTips(globalProperties, "请输入用户名");
    return;
  }
  loading.value = true;
  try {
    const parsed = await PostUserParse([name]);
    if (parsed.code !== 0) {
      ShowErrorTips(globalProperties, parsed.code);
      return;
    }
    // PostUserParse 未标注返回类型，就地收窄
    const users = (parsed.data?.users ?? []) as { id: number; username: string }[];
    if (users.length === 0) {
      applyAuth(null);
      ShowErrorTips(globalProperties, `未找到用户「${name}」`);
      return;
    }
    const res = await GetPermissionUserAuth(users[0].id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    applyAuth(res.data);
  } finally {
    loading.value = false;
  }
};

/** 保存：一次提交所有改动过的部分 */
const handleSave = async () => {
  const authValue = auth.value;
  if (authValue === null || !dirty.value) {
    return;
  }
  saving.value = true;
  try {
    if (rolesDirty.value) {
      const res = await PostPermissionUserRoleSave({
        user_id: authValue.user_id,
        roles: directRoles.value,
      });
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }
    }
    if (groupsDirty.value) {
      const res = await PostPermissionUserGroupSave({
        user_id: authValue.user_id,
        group_ids: groupIds.value,
      });
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }
    }
    ShowTextTipsSuccess(globalProperties, "已保存");
    // 重新拉取，让「最终生效」立即反映最新状态
    const refreshed = await GetPermissionUserAuth(authValue.user_id);
    if (refreshed.code === 0) {
      applyAuth(refreshed.data);
    }
  } finally {
    saving.value = false;
  }
};

/** 放弃本次未保存的改动 */
const handleReset = () => {
  applyAuth(auth.value);
};
</script>

<template>
  <div class="permission-panel">
    <div class="panel-toolbar">
      <t-input
        v-model="searchName"
        placeholder="输入用户名后回车查询"
        style="width: 260px"
        clearable
        @enter="handleSearch"
      />
      <t-button theme="primary" :loading="loading" @click="handleSearch">查询授权</t-button>
      <span class="panel-hint">按用户名查询某人的直接角色、所属用户组与最终生效的权限点。</span>
    </div>

    <template v-if="auth !== null">
      <t-alert v-if="isSelf" theme="warning" class="self-alert">
        <template #message>
          这是你自己的账号。为避免自提权，系统<strong>不允许</strong>任何人修改自己的授权
          （保存会被拒绝），请让另一位管理员代为操作。
        </template>
      </t-alert>

      <t-card :title="`${auth.nickname || auth.username}（${auth.username}）`" class="auth-card">
        <template #actions>
          <t-space size="small" align="center">
            <t-tag v-if="auth.is_super" theme="warning" variant="light">超级管理员</t-tag>
            <t-tag v-if="dirty" theme="primary" variant="light">有未保存的修改</t-tag>
          </t-space>
        </template>

        <t-form label-align="top">
          <t-form-item label="直接授予的角色">
            <t-select
              v-model="directRoles"
              :options="roleOptions"
              multiple
              clearable
              placeholder="不选择表示没有直接角色"
              :disabled="isSelf"
            />
            <template #help>
              只包含「直接授予本人」的角色；通过用户组继承的角色在下方维护。
            </template>
          </t-form-item>

          <t-form-item label="所属用户组">
            <t-select
              v-model="groupIds"
              :options="groupOptions"
              multiple
              clearable
              placeholder="不选择表示不属于任何用户组"
              :disabled="isSelf"
            />
            <template #help>
              用户组带来的角色同样计入有效权限；把一个高权限组加给某人前请确认影响面。
            </template>
          </t-form-item>
        </t-form>

        <!-- 两处改动合成一次保存：此前是两个独立按钮，改了上面没点保存就去点下面时，
             第一个改动会被静默丢弃（刷新会用服务端结果覆盖本地副本） -->
        <div v-if="!isSelf" class="save-bar">
          <t-button
            theme="primary"
            :loading="saving"
            :disabled="!dirty"
            @click="handleSave"
          >
            保存
          </t-button>
          <t-button variant="outline" :disabled="!dirty || saving" @click="handleReset">
            放弃修改
          </t-button>
          <span class="panel-hint">
            <template v-if="dirty">
              将保存：<template v-if="rolesDirty">直接角色</template
              ><template v-if="rolesDirty && groupsDirty">、</template
              ><template v-if="groupsDirty">所属用户组</template>
            </template>
            <template v-else>没有需要保存的改动</template>
          </span>
        </div>

        <t-divider>最终生效</t-divider>

        <div class="effective">
          <div class="effective-row">
            <span class="effective-label">有效角色</span>
            <t-space size="small" break-line>
              <t-tag v-for="key in auth.roles" :key="key" size="small" variant="light">
                {{ key }}
              </t-tag>
              <span v-if="auth.roles.length === 0" class="empty-text">无</span>
            </t-space>
          </div>

          <div v-if="rolesFromGroups.length > 0" class="effective-row">
            <span class="effective-label">用户组带来的角色</span>
            <t-space size="small" break-line>
              <t-tag
                v-for="key in rolesFromGroups"
                :key="key"
                size="small"
                theme="primary"
                variant="light"
              >
                {{ key }}
              </t-tag>
            </t-space>
          </div>

          <div class="effective-row">
            <span class="effective-label">有效权限点</span>
            <t-space size="small" break-line>
              <t-tag
                v-for="key in auth.permissions"
                :key="key"
                size="small"
                theme="success"
                variant="light"
              >
                {{ permissionNames[key] ?? key }}
                <span class="permission-origin">{{ permissionSource[key] }}</span>
              </t-tag>
              <span v-if="auth.permissions.length === 0" class="empty-text">无</span>
            </t-space>
          </div>

          <div class="effective-note">
            标注说明：「直接」= 撤掉上面的直接角色就会失去；「继承」= 来自用户组，需退组或改组的角色
            才会失去；「直接 + 继承」= 两条来源都有，只撤一条不会失去。
          </div>
        </div>
      </t-card>
    </template>

    <t-empty v-else description="输入用户名查询该用户的授权情况" />
  </div>
</template>

<style scoped>
