  margin-bottom: 12px;
}

.auth-card {
  margin-top: 8px;
}

.save-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  flex-wrap: wrap;
}

.effective-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

.effective-label {
  color: var(--td-text-color-secondary);
  min-width: 130px;
}

.effective-note {
  color: var(--td-text-color-placeholder);
  font-size: 12px;
  line-height: 1.6;
}

